#version 330
// God Wand Blue/Red/Purple VFX. UV v < 2: the VFX atlas, tinted (no alpha cut-off, so edges stay soft).
// UV v >= 2: a procedural effect: id = floor(v) - 2, seed = floor(u), local (0..1, 0..1) = the fractional parts.
// Colour comes from a ramp built from the vertex tint (dark, tint, white hot); vertex alpha is the master alpha.

uniform sampler2D Sampler0;
layout(std140) uniform DynamicTransforms {
    mat4 ModelViewMat;
    vec4 ColorModulator;
    vec3 ModelOffset;
    mat4 TextureMat;
};
layout(std140) uniform Globals {
    ivec3 CameraBlockPos;
    vec3 CameraOffset;
    vec2 ScreenSize;
    float GlintAlpha;
    float GameTime;
    int MenuBlurRadius;
    int UseRgss;
};
// Seconds: GameTime is the game time over 24000 ticks (20 minutes).
#define VfxTime (GameTime * 1200.0)

in vec2 texCoord0;
in vec4 vertexColor;
